/// <summary>
/// Logic block needed to create a transfer journal
/// </summary>
class MwmsLogicBlockCreateTransferJournal extends MwmsLogicBlockjournalsCommon implements TFMLogicBlockDataCollectionInterface
{
}

Method.Source:
/// <summary>
/// This method provides the header fields, that are needed to find out which data should be collected.
/// </summary>
/// <returns>A MobReferenceDataConfiguration object, containing registration collectors for the header.</returns>
public TFMReferenceDataConfiguration headerFieldsNeeded()
{
    return components.getHeaders();
}

public static MwmsLogicBlockCreateTransferJournal Construct()
{
    return new MwmsLogicBlockCreateTransferJournal();
}

protected void new()
{
    super();

    categories.add("@SYS6437");
    categories.add("@SYS8801");
    components.addComponent(new MwmsLogicComponentInventoryJournalsCommonHeader());
}

public Set autoCreatedProcesses()
{
    Set ret = super();
    TFMProcess process = TFMProcess::Construct('CreateTransferJournal');
    process.addBlock(this);
    ret.add(Process);        
    return ret;
}

public str blockIcon()
{
    return methodstr(MobimageHandlerCombinedImages, transferJournalIcon);
}

/// <summary>
/// Name of the block Type.
/// </summary>
/// <returns>Name of the block</returns>
public Name blockName()
{
    return "@MobileWMS:CreateTransferJournal";
}

/// <summary>
/// This method gives you the registration collectors for this data collection block.
/// </summary>
/// <returns>A collection of registration collectors.</returns>
public TFMRegistrationCollectors registrationCollectors()
{
    return null;
}

/// <summary>
/// This method is called before the post method, and gives the option to add extra registration collectors for the user to be prompted for before the post method is executed.
/// </summary>
/// <returns>Returns a MobRegistrationCollectors object if the user must be further prompted, otherwise it returns null</returns>
public TFMRegistrationCollectors prePostRegistrationCollectors()
{
    return null;
}

/// <summary>
/// The method executed when all data has been collected, and contains the posting logic.
/// </summary>
/// <returns>A MobPostResponseData object.</returns>
public TFMPostResponseData post()
{
    TFMPostResponseData                 response = TFMPostResponseData::Construct();
    InventJournalName			        inventJournalName;

    // Get the name of the journal to create
    inventJournalTable.clear();
    inventJournalName = InventJournalName::find(MobParameters::find().InventJournalNameTransfer,true);
    docRequest.addField(extendedTypeStr(JournalNameId),inventJournalName.JournalNameId);
    inventJournalTable.JournalType          = inventJournalType::Transfer;
    inventJournalTable = components.provideDataIfPossible(inventJournalTable);
    inventJournalTable.insert();

    response.parmResponseText("@MobileWMS:MEL47");

    return response;
}
